'use strict';
let state, page='Overview', search='', paymentFilter='All', currentQuarter=String(Math.ceil((new Date().getMonth()+1)/3)), currentYear=String(new Date().getFullYear());
const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n||0), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), round=n=>Math.round((n+Number.EPSILON)*100)/100;
const uid=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2), today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const base=p=>p.purchase/(p.currency==='INR'?p.exchange:1), product=id=>state.products.find(p=>p.id===id), refunded=id=>state.returns.find(r=>r.sale===id);
function allocation(p){let sh=state.shipments.find(s=>s.id===p.shipment);if(!sh)return 0;let group=state.products.filter(x=>x.shipment===sh.id);let measure=x=>sh.method==='value'?base(x)*x.qty:sh.method==='weight'?x.weight*x.qty:sh.method==='manual'?x.share:x.qty;let total=group.reduce((n,x)=>n+measure(x),0);return total?(sh.domestic+sh.international+sh.duty+sh.brokerage+sh.other)*measure(p)/total/p.qty:0;}
const shipCharge=s=>s.shippingCharge||0, saleRevenue=s=>s.price+shipCharge(s), shippingTax=s=>s.shippingTaxable??(s.taxable?shipCharge(s):0), taxableBase=s=>(s.taxable?s.price:0)+shippingTax(s);
const cost=p=>base(p)+p.packaging+allocation(p), msrp=p=>round(state.settings.pricing==='markup'?cost(p)*(1+state.settings.margin/100):cost(p)/(1-state.settings.margin/100));
function onhand(p){return p.qty-(p.openingSold||0)-state.sales.filter(s=>s.product===p.id).reduce((n,s)=>n+s.qty,0)+state.returns.filter(r=>r.restock).reduce((n,r)=>{let s=state.sales.find(s=>s.id===r.sale);return n+(s.product===p.id?s.qty:0);},0);}
const available=p=>onhand(p)-p.reserved;
function roundedLabelPrice(p){let cents=Math.ceil(msrp(p)*(1+(state.settings.tax||0)/100)*100-1e-7);return (Math.ceil((cents-99)/100)*100+99)/100;}
function suggestedSaleAmounts(p,qty=1,taxable=true,taxableShipping=0){let total=round(roundedLabelPrice(p)*qty),rate=taxable?(state.settings.tax||0)/100:0,price=round(total/(1+rate));return {price,tax:round(total-price+taxableShipping*rate)};}
function deletionReason(p){if(state.sales.some(s=>s.product===p.id))return 'This batch has recorded sales or refunds. Keep it to preserve transaction history.';if((p.openingSold||0)>0||(state.pending||[]).some(x=>x.product===p.id))return 'This batch has historical sales or review records. Keep it to preserve the ledger.';if(p.reserved>0)return 'Release this batch’s reservations before deleting it.';return '';}
async function deleteProduct(id){let p=product(id),reason=deletionReason(p);if(reason){notice(reason,true);return;}let warning=p.shipment?' Shared shipment costs will be reallocated to the remaining batches, which can change their pricing and profit.':'';if(!confirm('Delete '+p.name+' ('+p.sku+') and its colors/photos? This removes '+p.qty+' received pieces.'+warning))return;try{await change(s=>{let current=s.products.find(x=>x.id===id);if(deletionReason(current))throw new Error(deletionReason(current));s.products=s.products.filter(x=>x.id!==id);});notice('Inventory item deleted.');}catch(error){notice('Could not delete item: '+error.message,true);}}
function instagramEmbed(link){try{let u=new URL(link),m=u.pathname.match(/^\/(p|reel|tv)\/([A-Za-z0-9_-]+)\/?$/);return u.protocol==='https:'&&['www.instagram.com','instagram.com'].includes(u.hostname)&&m?`https://www.instagram.com/${m[1]}/${m[2]}/embed/`:'';}catch{return '';}}
function mediaFor(p,v){if(v)return {photo:v.photo||(instagramEmbed(v.instagram)?'':p.photo||''),link:v.instagram||p.instagram||''};let variants=p.variants||[];return {photo:p.photo||variants.find(v=>v.photo)?.photo||'',link:p.instagram||variants.find(v=>instagramEmbed(v.instagram))?.instagram||''};}
function mediaMarkup(p,v){let media=mediaFor(p,v),title=v?p.name+' · '+v.name:p.name,embed=instagramEmbed(media.link);if(media.photo)return `<button class="photo-button" data-media="${esc(p.id)}" ${v?`data-color="${esc(v.id)}"`:''} aria-label="View photo of ${esc(title)}"><img class="product-photo" src="${esc(media.photo)}" alt="${esc(title)}" loading="lazy"></button>`;if(embed)return `<div class="instagram-preview"><iframe src="${esc(embed)}" title="Instagram preview of ${esc(title)}" loading="lazy" referrerpolicy="no-referrer"></iframe><small>Instagram preview may be unavailable. <a href="${esc(media.link)}" target="_blank" rel="noopener">Open Instagram ↗</a> or add a product photo.</small></div>`;return `<div class="swatch">${esc(p.material||'Saree')}</div>`;}
function mediaDialog(pid,vid){let p=product(pid),v=(p.variants||[]).find(v=>v.id===vid);dialog(v?p.name+' · '+v.name:p.name,mediaMarkup(p,v));$('#modalContent .product-photo')?.classList.add('photo-large');}
function wireMedia(){document.querySelectorAll('[data-media]').forEach(b=>b.onclick=()=>mediaDialog(b.dataset.media,b.dataset.color));document.querySelectorAll('[data-instagram-preview]').forEach(b=>b.onclick=()=>mediaDialog(b.dataset.instagramPreview,b.dataset.color));}

function variantSold(p,id){return state.sales.filter(s=>s.product===p.id&&(s.variant||'')===id).reduce((n,s)=>n+s.qty-(refunded(s.id)?.restock?s.qty:0),0)+(id===''?(p.openingSold||0):0);}
const variantStock=(p,v)=>v.qty-variantSold(p,v.id), unassignedStock=p=>p.qty-(p.variants||[]).reduce((n,v)=>n+v.qty,0)-variantSold(p,'');
const saleColor=s=>(product(s.product).variants||[]).find(v=>v.id===s.variant)?.name||'Unassigned';
function variantSummary(p){return (p.variants||[]).length?`<div class="variant-list">${p.variants.map(v=>`<div class="variant-tile">${v.photo?`<button class="photo-button" data-media="${esc(p.id)}" data-color="${esc(v.id)}" aria-label="View photo of ${esc(v.name)}"><img src="${esc(v.photo)}" alt="${esc(v.name)}" loading="lazy"></button>`:instagramEmbed(v.instagram)?`<button class="quiet" data-instagram-preview="${esc(p.id)}" data-color="${esc(v.id)}">Preview Instagram</button>`:''}<strong>${esc(v.name)}</strong><small>${variantStock(p,v)} on hand</small>${v.instagram?`<a href="${esc(v.instagram)}" target="_blank" rel="noopener">Instagram ↗</a>`:''}</div>`).join('')}</div><small>${unassignedStock(p)} unassigned on hand · reservations apply to the batch</small>`:'';}
function variantsForm(pid){let p=product(pid),draft=structuredClone(p.variants||[]),uploads=new Set(),uploadError=null;
 dialog('Colors / variants · '+p.sku,`<p>Each color shares this batch’s landed cost and suggested price. Assign quantities from unsold, unassigned stock. Past sales remain unassigned.</p><form id="editForm"><div id="variantRows"></div><p id="variantBalance" class="note"></p><button type="button" class="quiet" id="addVariant">Add color +</button>${foot('Save variants')}</form>`);
 function balance(){let used=draft.reduce((n,v)=>n+Number(v.qty||0),0);$('#variantBalance').textContent=`${used} pieces assigned to colors · ${p.qty-variantSold(p,'')-used} pieces remaining unassigned. Quantity assigned includes recorded sales of that color. Reservations stay at the batch level.`;}
 function rows(){ $('#variantRows').innerHTML=draft.map(v=>`<section class="variant-editor" data-variant="${esc(v.id)}"><div class="fields">${field('Color / variant name','name',v.name,'text','required maxlength="100"')}${num('Pieces assigned to this color','qty',v.qty,1,1)}${field('Instagram post / reel URL','instagram',v.instagram||'','url')}<label>Color photo<input type="file" data-photo accept="image/*"></label></div>${v.photo?`<img class="variant-preview" src="${esc(v.photo)}" alt="Color photo">`:''}<div class="row actions"><small>${variantSold(p,v.id)} net sold</small><button type="button" class="quiet" data-remove-photo>Remove photo</button><button type="button" class="quiet" data-remove>Remove color</button></div></section>`).join('');
 $('#variantRows').querySelectorAll('[data-variant]').forEach(el=>{let v=draft.find(x=>x.id===el.dataset.variant);el.oninput=e=>{if(e.target.name){v[e.target.name]=e.target.name==='qty'?Number(e.target.value):e.target.value;balance();}};el.querySelector('[data-remove]').onclick=()=>{if(state.sales.some(s=>s.product===p.id&&s.variant===v.id))return formError(new Error('A color used in a recorded sale must be kept.'));draft=draft.filter(x=>x.id!==v.id);rows();};el.querySelector('[data-remove-photo]').onclick=()=>{if(uploads.size)return formError(new Error('Wait for the photo to finish loading.'));v.photo='';rows();};el.querySelector('[data-photo]').onchange=e=>{let file=e.target.files[0];if(!file)return;uploadError=null;let task=compressPhoto(file).then(photo=>{v.photo=photo;let img=el.querySelector('img');if(!img){img=document.createElement('img');img.className='variant-preview';img.alt='Color photo';el.append(img);}img.src=photo;}).catch(err=>{uploadError=err;formError(err);throw err;});uploads.add(task);task.finally(()=>uploads.delete(task)).catch(()=>{});};});balance(); }
 $('#addVariant').onclick=()=>{draft.push({id:uid(),name:'',qty:1,instagram:'',photo:''});rows();};rows();
 wireForm(async()=>{await Promise.all([...uploads]);if(uploadError)throw uploadError;await change(s=>{s.products.find(x=>x.id===pid).variants=draft;});});
}
async function compressPhoto(file){try{let bitmap=await createImageBitmap(file);let scale=Math.min(1,600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);let photo=canvas.toDataURL('image/jpeg',.65);bitmap.close();if(photo.length>1000000)throw new Error();return photo;}catch(e){throw new Error('Could not read that image. Try a JPEG or PNG photo.');}}

function stats(sales,returns,businessExpenses=[]){let productRevenue=sales.reduce((n,s)=>n+s.price,0),shipping=sales.reduce((n,s)=>n+shipCharge(s),0),tax=sales.reduce((n,s)=>n+s.tax,0),cogs=sales.reduce((n,s)=>n+cost(product(s.product))*s.qty,0),expenses=sales.reduce((n,s)=>n+s.expense,0),shippingCost=sales.reduce((n,s)=>n+(s.shippingCost||0),0),missingShipping=sales.filter(s=>s.shippingCost===null).length;for(let r of returns){let s=state.sales.find(s=>s.id===r.sale);productRevenue-=s.price;shipping-=shipCharge(s);tax-=s.tax;if(r.restock)cogs-=cost(product(s.product))*s.qty;}let revenue=productRevenue+shipping,miscExpenses=round(businessExpenses.reduce((n,e)=>n+e.amount,0));return {miscExpenses,productRevenue,shipping,shippingCost,missingShipping,revenue,tax,cogs,expenses,profit:revenue-cogs-expenses-shippingCost-miscExpenses};}
async function api(route,body,timeoutMs=20000){let controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeoutMs);try{let res=await fetch(route,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:controller.signal});let data=await res.json().catch(()=>({error:res.status===401?'Sign in to continue':`The app service returned HTTP ${res.status}. Please try again.`}));if(!res.ok)throw Object.assign(new Error(data.error||'Request failed'),{status:res.status});return data;}catch(e){if(e.name==='AbortError')throw Object.assign(new Error(body?'The save request timed out. Refresh to check whether it saved before trying again.':'The inventory request timed out. Please try again.'),{timeout:true});throw e;}finally{clearTimeout(timer);}}
function notice(msg,error=false){$('#notice').innerHTML=msg?`<div class="${error?'alert':'note'}">${esc(msg)}</div>`:'';}
let loading=false,defaultsFeedback='';
async function load(){if(loading)return;loading=true;$('#refresh').disabled=true;$('#view').setAttribute('aria-busy','true');function progress(message){notice(message);if(!state)$('#view').innerHTML=`<div class="empty" role="status"><h2>Loading your inventory…</h2><p>${esc(message)}</p></div>`;}
try{for(let attempt=1;attempt<=3;attempt++){progress(attempt===1?'Connecting to your boutique ledger…':`The service is taking longer than usual. Retrying (${attempt} of 3)…`);try{let next=await api('/api/state');if(!next||!Array.isArray(next.products)||!Array.isArray(next.shipments)||!Array.isArray(next.sales)||!Array.isArray(next.returns)||!next.settings)throw new Error('The app did not receive a valid inventory response. Please try again.');state=next;notice('');render();return;}catch(e){if(e.status===401){login();return;}let retryable=e.timeout||e instanceof TypeError||[500,502,503,504].includes(e.status);if(retryable&&attempt<3){await new Promise(resolve=>setTimeout(resolve,2000));continue;}throw e;}}}
catch(e){notice(e.message,true);if(!state){$('#view').innerHTML=`<div class="empty"><h2>Unable to load inventory</h2><p>${esc(e.message)}</p><p class="muted">Your saved records have not been replaced. Check your connection and try again.</p><button id="retryLoad">Try again</button></div>`;$('#retryLoad').onclick=load;}}
finally{loading=false;$('#refresh').disabled=false;$('#view').setAttribute('aria-busy','false');}}

async function change(fn){let next=structuredClone(state);fn(next);let result=await api('/api/state',next);state=result;render();}
function login(){if($('#logout'))$('#logout').hidden=true;dialog('Welcome to your studio',`<p class="muted">Enter the access code displayed in the app’s computer window.</p><form id="login"><label>Access code<input name="pin" inputmode="numeric" autocomplete="off" required></label><div class="form-foot"><button>Open ledger</button></div></form>`,false);$('#login').onsubmit=async e=>{e.preventDefault();try{await api('/api/login',{pin:new FormData(e.target).get('pin')});$('#modal').close();await load();}catch(err){formError(err);}};}
function dialog(title,body,closable=true){$('#modalContent').innerHTML=`<div class="row"><h2>${esc(title)}</h2>${closable?'<button class="quiet" data-close aria-label="Close dialog">✕</button>':''}</div><div id="formError" role="alert"></div>${body}`;if(!$('#modal').open)$('#modal').showModal();$('#modal').onkeydown=e=>{if(!closable&&e.key==='Escape')e.preventDefault();};$('#modalContent').querySelector('[data-close]')?.addEventListener('click',()=>$('#modal').close());}
function formError(e){$('#formError').innerHTML=`<div class="alert">${esc(e.message)}</div>`;}
const field=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const num=(label,name,value=0,min=0,step='.01')=>field(label,name,value,'number',`min="${min}" step="${step}" required`);
const select=(label,name,options,value)=>`<label>${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const foot=label=>`<div class="form-foot"><button type="button" class="quiet" data-cancel>Cancel</button><button>${label}</button></div>`;
function wireForm(handler){let f=$('#editForm');f.querySelector('[data-cancel]').onclick=()=>$('#modal').close();f.onsubmit=async e=>{e.preventDefault();let btn=f.querySelector('button:not([type])');if(btn)btn.disabled=true;try{await handler(new FormData(f));$('#modal').close();notice('Saved to your computer.');}catch(err){formError(err);}finally{if(btn)btn.disabled=false;}};}
function render(){if($('#logout'))$('#logout').hidden=false;let pages=['Overview','Inventory','Shipments','Sales','Expenses','Historical review','Quarterly report','Settings & backup'];$('#nav').innerHTML=pages.map((p,i)=>`<button class="${page===p?'active':''}" data-page="${esc(p)}">${['◈','▦','↗','↔','$','◷','▤','⚙'][i]} &nbsp; ${p}</button>`).join('');$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{page=b.dataset.page;notice('');render();});$('#title').textContent=page;$('#eyebrow').textContent=state.settings.name+' / Boutique ledger';$('#connection').textContent='Saved locally · revision '+state.revision;({Overview:overview,Inventory:inventory,Shipments:shipments,Sales:sales,Expenses:expenses,'Historical review':historicalReview,'Quarterly report':report,'Settings & backup':settings})[page]();}
function cards(items){return '<div class="cards">'+items.map(([label,val,sub])=>`<div class="card"><span class="kicker">${label}</span><strong class="number">${val}</strong><small>${sub}</small></div>`).join('')+'</div>';}
function overview(){let t=stats(state.sales,state.returns,state.businessExpenses||[]),units=state.products.reduce((n,p)=>n+onhand(p),0),value=state.products.reduce((n,p)=>n+cost(p)*onhand(p),0);$('#view').innerHTML=`<div class="hero"><div><span class="kicker">Made for your next chapter</span><h2>Know what each saree earns.</h2><p class="muted">From the first purchase to the final sale, keep every detail together.</p></div><button id="addSale">Record a sale +</button></div>${cards([['Net sales',money(t.revenue),'All time · sales tax excluded'],['Gross profit',money(t.productRevenue-t.cogs),'Product sales less landed cost · before expenses'],['Profit after expenses',money(t.profit),t.missingShipping?'Includes entered expenses · postage missing; profit incomplete':'Includes selling, shipping & miscellaneous expenses'],['Tax collected',money(t.tax),'Net of recorded refunds']])}<div class="two"><div class="panel"><div class="row"><h2>Recent sales</h2><span class="tag">${state.sales.length} recorded</span></div>${saleTable(state.sales.slice(-5).reverse(),false)}${state.pending?.some(p=>p.qty>0)?'<p class="note">Imported sales await review. Inventory reflects those sold pieces; sales and profit reports include only reviewed transactions.</p>':''}</div><div class="panel"><h2>Your pricing guide</h2><div class="row"><span>Inventory value · ${units} pieces on hand</span><strong>${money(value)}</strong></div><span class="kicker">Target ${state.settings.pricing==='markup'?'markup':'gross margin'}</span><div class="row"><strong style="font-size:36px">${state.settings.margin}%</strong><span class="tag">Adjust in settings</span></div><p class="muted">${state.settings.pricing==='markup'?'List price = landed cost × (1 + markup). A $50 cost at 50% markup gives a $75 price.':'List price = landed cost ÷ (1 − margin). A $50 cost at 50% margin gives a $100 price.'}</p><hr style="border:0;border-top:1px solid var(--line)"><div class="row"><span>Recorded selling expenses</span><strong>${money(t.expenses)}</strong></div><div class="row"><span>Miscellaneous business expenses</span><strong>${money(t.miscExpenses)}</strong></div><div class="row"><span>Profit after all entered expenses</span><strong>${money(t.profit)}</strong></div><div class="row"><span>Shipping charged to customers</span><strong>${money(t.shipping)}</strong></div><div class="row"><span>Recorded shipping expenses</span><strong>${money(t.shippingCost)}</strong></div><small>${t.missingShipping?t.missingShipping+' shipping expense(s) not entered; profit is incomplete.':'Does not include overhead that you have not entered.'}</small></div></div><div class="note">Start with a shipment, add its products, then enter the actual shipping and duty costs. Shared costs are allocated across all products in that shipment.</div>`;$('#addSale').onclick=()=>saleForm();}
function inventory(){let list=state.products.filter(p=>(p.name+' '+p.sku+' '+p.vendor+' '+(p.variants||[]).map(v=>v.name).join(' ')).toLowerCase().includes(search.toLowerCase()));$('#view').innerHTML=`<div class="toolbar"><input id="search" aria-label="Search inventory" placeholder="Search name, SKU, or vendor…" value="${esc(search)}"><span class="spacer"></span><button class="quiet" id="printLabels">Price labels</button><button id="addProduct">Add product +</button></div><div class="grid inventory-grid">${list.map(p=>`<article class="panel inventory-card"><div class="inventory-media">${mediaMarkup(p)}</div><div class="row"><span class="kicker" title="${esc(p.sku)}">${esc(p.sku)}</span><span class="tag ${available(p)?'':'warn'}">${available(p)} available</span></div><h3 title="${esc(p.name)}">${esc(p.name)}</h3><small class="product-meta" title="${esc(p.vendor||'Vendor not entered')} · ${esc(p.date)}">${esc(p.vendor||'Vendor not entered')} · ${esc(p.date)}</small><div class="row"><span class="muted">Landed cost / piece</span><strong>${money(cost(p))}</strong></div><div class="row"><span class="muted">Suggested list price</span><strong>${money(msrp(p))}</strong></div><small>${onhand(p)} on hand · ${p.reserved} reserved · ${p.qty} received</small><div class="row"><small>Suggested total incl. default tax</small><strong>${money(msrp(p)*(1+state.settings.tax/100))}</strong></div><div class="label-price"><strong>Round up to .99: ${money(roundedLabelPrice(p))} incl. tax</strong><small>Price label · ${state.settings.tax}% default tax included</small></div>${variantSummary(p)}<div class="row actions"><button class="quiet" data-labels="${p.id}">Price labels</button><button class="quiet" data-variants="${p.id}">Colors / variants</button><button data-sell="${p.id}" ${available(p)>0?'':'disabled'}>Sell</button><button class="quiet" data-edit="${p.id}">Edit / costs</button><button class="danger" data-delete-product="${p.id}">Delete</button>${p.instagram?`<a class="button quiet" href="${esc(p.instagram)}" target="_blank" rel="noopener">Instagram ↗</a>`:''}</div></article>`).join('')}</div>${list.length?'':'<div class="empty"><h2>Your collection starts here</h2><p class="muted">Add your first product and its purchase costs.</p></div>'}`;$('#search').oninput=e=>{search=e.target.value;let pos=e.target.selectionStart;inventory();$('#search').focus();$('#search').setSelectionRange(pos,pos);};$('#addProduct').onclick=()=>productForm();$('#printLabels').onclick=()=>labelsForm(list);document.querySelectorAll('[data-labels]').forEach(b=>b.onclick=()=>labelsForm([product(b.dataset.labels)]));wireMedia();document.querySelectorAll('[data-variants]').forEach(b=>b.onclick=()=>variantsForm(b.dataset.variants));document.querySelectorAll('[data-delete-product]').forEach(b=>b.onclick=()=>deleteProduct(b.dataset.deleteProduct));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>productForm(b.dataset.edit));document.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>saleForm(b.dataset.sell));}
function productForm(id){let p=id?product(id):{id:uid(),name:'',sku:'',vendor:'',material:'',date:today(),qty:1,reserved:0,currency:'INR',purchase:0,exchange:state.settings.exchange,packaging:0,weight:1,share:1,shipment:'',instagram:'',photo:'',notes:''};dialog(id?'Edit product & costs':'Add a product',`<form id="editForm"><div class="fields">${field('Product name','name',p.name,'text','required maxlength="160"')}${field('SKU / batch identifier','sku',p.sku,'text','required maxlength="80"')}${field('Vendor','vendor',p.vendor)}${field('Material / style','material',p.material)}${field('Purchase date','date',p.date,'date','required')}${select('Shipment','shipment',[['','No shipment'],...state.shipments.map(s=>[s.id,s.name])],p.shipment)}${num('Quantity received','qty',p.qty,1,1)}${num('Reserved quantity','reserved',p.reserved,0,1)}${select('Purchase currency','currency',[['INR','INR'],['USD','USD']],p.currency)}${num('Purchase cost per piece','purchase',p.purchase)}${num('INR per 1 USD (recorded exchange rate)','exchange',p.exchange,.000001,'.000001')}${num('Packaging / other per piece · USD','packaging',p.packaging)}${num('Weight per piece (any consistent unit)','weight',p.weight,0,'.001')}${num('Manual shipment allocation shares (whole batch)','share',p.share)}${field('Instagram post / reel URL','instagram',p.instagram,'url')}<label>Product photo<input id="photo" type="file" accept="image/*"></label><label class="full">Notes<textarea name="notes">${esc(p.notes)}</textarea></label></div><div id="costPreview" class="preview"></div><div class="note">${esc(p.notes)}</div><small>For another purchase of the same SKU, add a separate product batch. Shipping, duties, and tariffs are entered on its shipment.</small>${foot('Save product')}</form>`);let newPhoto=p.photo;$('#photo').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;let bitmap=await createImageBitmap(file);let scale=Math.min(1,900/Math.max(bitmap.width,bitmap.height));let canvas=document.createElement('canvas');canvas.width=bitmap.width*scale;canvas.height=bitmap.height*scale;canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);newPhoto=canvas.toDataURL('image/jpeg',.7);bitmap.close();}catch(e){formError(new Error('Could not read that image. Try a JPEG or PNG photo.'));}};function build(f){return {...p,...Object.fromEntries(f),qty:+f.get('qty'),reserved:+f.get('reserved'),purchase:+f.get('purchase'),exchange:+f.get('exchange'),packaging:+f.get('packaging'),weight:+f.get('weight'),share:+f.get('share'),photo:newPhoto};}function preview(){let draft=build(new FormData($('#editForm')));let old=state;state={...state,products:[...state.products.filter(x=>x.id!==draft.id),draft]};$('#costPreview').innerHTML=`Purchase: ${money(base(draft))} · Shipping & duty: ${money(allocation(draft))} / piece<br><strong>Landed cost: ${money(cost(draft))} · Suggested price: ${money(msrp(draft))}</strong>`;state=old;}$('#editForm').oninput=preview;preview();wireForm(async f=>change(s=>{let draft=build(f);let i=s.products.findIndex(x=>x.id===draft.id);if(i<0)s.products.push(draft);else s.products[i]=draft;}));}
function shipments(){$('#view').innerHTML=`<div class="toolbar"><p class="muted">Group purchases and share the journey’s costs.</p><span class="spacer"></span><button id="addShipment">Add shipment +</button></div>${state.shipments.map(s=>{let ps=state.products.filter(p=>p.shipment===s.id),total=s.domestic+s.international+s.duty+s.brokerage+s.other;return `<div class="panel section-gap"><div class="row"><div><span class="kicker">${s.estimated?'Estimated costs':'Actual recorded costs'}</span><h2 style="margin-top:8px">${esc(s.name)}</h2></div><button class="quiet" data-shipment="${s.id}">Edit shipment</button></div><div class="row"><span>${ps.length} batches · ${ps.reduce((n,p)=>n+p.qty,0)} pieces · allocated by ${s.method}</span><strong>${money(total)}</strong></div><small>India shipping ${money(s.domestic)} · USA shipping ${money(s.international)} · Duty ${money(s.duty)} · Brokerage ${money(s.brokerage)} · Other ${money(s.other)}</small><p class="muted">${esc(s.notes)}</p></div>`;}).join('')}${state.shipments.length?'':'<div class="empty"><h2>Every shipment, accounted for</h2><p class="muted">Enter total shipping and duty costs in USD. Then assign products to this shipment.</p></div>'}<div class="note">Changing shipment costs updates landed costs and profit reports for associated products, including past sales. Keep a quarterly export when you file. Tariffs are entered manually from shipment documents; this app does not determine customs classifications.</div>`;$('#addShipment').onclick=()=>shipmentForm();document.querySelectorAll('[data-shipment]').forEach(b=>b.onclick=()=>shipmentForm(b.dataset.shipment));}
function shipmentForm(id){let s=id?state.shipments.find(x=>x.id===id):{id:uid(),name:'',method:'quantity',domestic:0,international:0,duty:0,brokerage:0,other:0,estimated:true,notes:''};dialog('Shipment costs',`<form id="editForm"><div class="fields">${field('Shipment name / invoice reference','name',s.name,'text','required')}${select('Allocate shared costs by','method',[['quantity','Quantity'],['value','Purchase value (USD)'],['weight','Weight × quantity'],['manual','Manual batch shares']],s.method)}${num('Vendor → warehouse in India · USD','domestic',s.domestic)}${num('India → USA shipping · USD','international',s.international)}${num('Tariffs / duties · USD','duty',s.duty)}${num('Customs / brokerage · USD','brokerage',s.brokerage)}${num('Other shipment costs · USD','other',s.other)}${select('Cost status','estimated',[['yes','Estimated'],['no','Actual recorded']],s.estimated?'yes':'no')}<label class="full">Notes / conversion details<textarea name="notes">${esc(s.notes)}</textarea></label></div><p class="muted">Enter shipment totals once; do not also include these amounts in the product purchase cost. Convert INR shipping invoices to USD before entry.</p>${foot('Save shipment')}</form>`);wireForm(async f=>change(next=>{let item={...s,...Object.fromEntries(f),estimated:f.get('estimated')==='yes'};['domestic','international','duty','brokerage','other'].forEach(k=>item[k]=+f.get(k));let i=next.shipments.findIndex(x=>x.id===item.id);if(i<0)next.shipments.push(item);else next.shipments[i]=item;}));}
function saleTable(list,actions=true){if(!list.length)return '<p class="muted">No sales recorded yet.</p>';return `<div class="table-wrap"><table><thead><tr><th>Date / customer</th><th>Product</th><th>Payment</th><th>Product sale</th><th>Shipping charged</th><th>Shipping expense</th><th>Tax</th><th>Total paid</th>${actions?'<th></th>':''}</tr></thead><tbody>${list.map(s=>`<tr><td>${esc(s.date)}<br><small>${esc(s.reference||s.id.slice(0,8))}</small></td><td>${esc(product(s.product).name)} × ${s.qty}<br><small>${esc(saleColor(s))}</small><br><small>${refunded(s.id)?'Refunded '+esc(refunded(s.id).date):esc(product(s.product).sku)}</small></td><td>${s.payment}</td><td>${money(s.price)}</td><td>${money(shipCharge(s))}</td><td>${s.shippingCost===null?'Not entered':money(s.shippingCost||0)}</td><td>${money(s.tax)}</td><td>${money(saleRevenue(s)+s.tax)}</td>${actions?`<td><button class="quiet" data-edit-sale="${s.id}">Edit</button> <button class="quiet" data-shipping="${s.id}">Shipping</button> <button class="quiet" data-refund="${s.id}" ${refunded(s.id)?'disabled':''}>Full refund</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;}

function expenses(){let list=(state.businessExpenses||[]).slice().sort((a,b)=>b.date.localeCompare(a.date));$('#view').innerHTML=`<div class="toolbar"><span class="spacer"></span><button class="quiet" id="exportExpenses">Export expenses CSV</button><button id="addExpense">Add expense +</button></div>${cards([['Business expenses',money(list.reduce((n,e)=>n+e.amount,0)),'All time · USD'],['Entries',list.length,'Standalone expenses']])}<div class="panel">${list.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Description / payee</th><th>Category</th><th>Payment</th><th>Amount</th><th>Actions</th></tr></thead><tbody>${list.map(e=>`<tr><td>${esc(e.date)}</td><td>${esc(e.description)}<br><small>${esc(e.payee)}${e.notes?'<br>'+esc(e.notes):''}</small></td><td>${esc(e.category)}</td><td>${esc(e.payment)}</td><td>${money(e.amount)}</td><td><button class="quiet" data-edit-expense="${esc(e.id)}">Edit</button> <button class="danger" data-delete-expense="${esc(e.id)}">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No miscellaneous expenses recorded yet.</p>'}</div><p class="note">Record event vendor fees, advertising, supplies, and other business overhead in USD on the date paid. These reduce profit, without changing stock, label prices, or the sales-tax worksheet. Do not enter costs already included in a product, shipment, or sale again.</p>`;$('#addExpense').onclick=()=>expenseForm();document.querySelectorAll('[data-edit-expense]').forEach(b=>b.onclick=()=>expenseForm(b.dataset.editExpense));document.querySelectorAll('[data-delete-expense]').forEach(b=>b.onclick=async()=>{let e=state.businessExpenses.find(e=>e.id===b.dataset.deleteExpense);if(!confirm('Delete expense "'+e.description+'" for '+money(e.amount)+'? Profit reports will change.'))return;try{await change(s=>s.businessExpenses=s.businessExpenses.filter(x=>x.id!==e.id));notice('Expense deleted.');}catch(err){notice(err.message,true);}});$('#exportExpenses').onclick=()=>download('boutique-expenses-'+today()+'.csv',csv([['Date','Description','Category','Payee / event','Payment','Amount USD','Notes'],...list.map(e=>[e.date,e.description,e.category,e.payee,e.payment,e.amount,e.notes])]),'text/csv;charset=utf-8');}
function expenseForm(id){let e=id?(state.businessExpenses||[]).find(e=>e.id===id):{id:uid(),date:today(),description:'',category:'Event vendor fee',payee:'',payment:'Other',amount:'',notes:''};dialog(id?'Edit expense':'Add miscellaneous expense',`<form id="editForm"><div class="fields">${field('Date paid','date',e.date,'date','required')}${field('Description','description',e.description,'text','required maxlength="160"')}${select('Category','category',['Event vendor fee','Advertising','Supplies','Travel','Other'].map(x=>[x,x]),e.category)}${field('Payee / event (optional)','payee',e.payee,'text','maxlength="160"')}${select('Payment method','payment',['Zelle','Venmo','Cash','Card','Bank transfer','Other'].map(x=>[x,x]),e.payment)}${num('Amount paid · USD','amount',e.amount,.01)}<label class="full">Notes / receipt reference<textarea name="notes" maxlength="2000">${esc(e.notes)}</textarea></label></div><p class="muted">Enter the total actually paid. Record this cost only once; it will reduce profit in its payment quarter.</p>${foot(id?'Save expense changes':'Save expense')}</form>`);wireForm(async f=>{let item={...e,...Object.fromEntries(f),amount:round(+f.get('amount'))};if(!item.description.trim()||!Number.isFinite(item.amount)||item.amount<=0)throw new Error('Enter a description and positive expense amount.');await change(s=>{s.businessExpenses??=[];if(id)s.businessExpenses=s.businessExpenses.map(x=>x.id===id?item:x);else s.businessExpenses.push(item);});});}

function sales(){let list=state.sales.filter(s=>paymentFilter==='All'||s.payment===paymentFilter).slice().reverse();$('#view').innerHTML=`<div class="toolbar"><select id="paymentFilter" aria-label="Filter payment method" style="max-width:200px">${['All','Zelle','Venmo','Cash','Other'].map(x=>`<option ${x===paymentFilter?'selected':''}>${x}</option>`).join('')}</select><span class="spacer"></span><button id="addSale">Record sale +</button></div><div class="panel">${saleTable(list)}</div><div class="note">Record the payment method only; payments happen outside this app. Each entry is one product batch. For a multi-product purchase, use the same reference on each entry. Recorded sales are kept as a ledger; full refunds are separate dated entries.</div>`;$('#paymentFilter').onchange=e=>{paymentFilter=e.target.value;sales();};$('#addSale').onclick=()=>saleForm();document.querySelectorAll('[data-edit-sale]').forEach(b=>b.onclick=()=>saleForm(undefined,b.dataset.editSale));document.querySelectorAll('[data-shipping]').forEach(b=>b.onclick=()=>shippingForm(b.dataset.shipping));document.querySelectorAll('[data-refund]').forEach(b=>b.onclick=()=>refundForm(b.dataset.refund));}
