function refundForm(id){let sale=state.sales.find(s=>s.id===id);dialog('Record full refund',`<p>Refund ${money(saleRevenue(sale)+sale.tax)} for ${esc(product(sale.product).name)} × ${sale.qty}. This records a refund already handled outside the app.</p><form id="editForm"><div class="fields">${field('Refund date','date',today(),'date','required')}${select('Inventory treatment','restock',[['yes','Restock returned pieces'],['no','Do not restock (damaged / not returned)']],'yes')}<label class="full">Reason<textarea name="notes" required></textarea></label></div>${foot('Record full refund')}</form>`);wireForm(async f=>change(s=>s.returns.push({id:uid(),sale:id,date:f.get('date'),restock:f.get('restock')==='yes',notes:f.get('notes')})));}
function inQuarter(date){return date.slice(0,4)===currentYear&&Math.ceil(Number(date.slice(5,7))/3)===Number(currentQuarter);}
function report(){let ss=state.sales.filter(s=>inQuarter(s.date)),rs=state.returns.filter(r=>inQuarter(r.date)),same=rs.filter(r=>inQuarter(state.sales.find(s=>s.id===r.sale).date)),prior=rs.filter(r=>!same.includes(r));let t=stats(ss,rs,(state.businessExpenses||[]).filter(e=>inQuarter(e.date))),gross=ss.reduce((n,s)=>n+saleRevenue(s),0),tax=ss.reduce((n,s)=>n+s.tax,0),nontax=ss.filter(s=>!s.taxable).reduce((n,s)=>n+saleRevenue(s),0),exemptShipping=ss.filter(s=>s.taxable).reduce((n,s)=>n+shipCharge(s)-shippingTax(s),0),deduction=same.reduce((n,r)=>n+saleRevenue(state.sales.find(s=>s.id===r.sale)),0),taxable=gross-nontax-exemptShipping-same.reduce((n,r)=>{let s=state.sales.find(s=>s.id===r.sale);return n+taxableBase(s);},0);$('#view').innerHTML=`<div class="toolbar"><select id="quarter" aria-label="Quarter" style="width:120px">${[1,2,3,4].map(x=>`<option value="${x}" ${String(x)===currentQuarter?'selected':''}>Quarter ${x}</option>`).join('')}</select><input id="year" aria-label="Year" type="number" min="2000" max="2200" value="${currentYear}" style="width:120px"><span class="spacer"></span><button id="export">Export quarterly CSV</button></div>${cards([['Sales before tax',money(gross),'Original sales in this quarter'],['Tax collected',money(tax),'Before refund adjustments'],['Net revenue',money(t.revenue),'Refunds dated in this quarter included'],['Gross profit',money(t.productRevenue-t.cogs),'Based on current landed costs']])}<div class="panel"><h2>CDTFA preparation worksheet</h2><div class="row"><span>Original sales including collected tax</span><strong>${money(gross+tax)}</strong></div><div class="row"><span>Sales tax included in that amount</span><strong>${money(tax)}</strong></div><div class="row"><span>Original sales excluding tax</span><strong>${money(gross)}</strong></div><div class="row"><span>Documented nontaxable sales (original entries)</span><strong>${money(nontax)}</strong></div><div class="row"><span>Documented nontaxable shipping on taxable product sales</span><strong>${money(exemptShipping)}</strong></div><div class="row"><span>Full refunds of sales from this quarter, excluding tax</span><strong>${money(deduction)}</strong></div><div class="row"><span>Taxable sales after same-quarter full refunds</span><strong>${money(taxable)}</strong></div><div class="row"><span>Earlier-quarter sales refunded this quarter</span><strong>${prior.length} · ${money(prior.reduce((n,r)=>n+saleRevenue(state.sales.find(s=>s.id===r.sale)),0))}</strong></div><div class="row"><span>Net tax held after all recorded refunds</span><strong>${money(t.tax)}</strong></div></div><div class="note">This is a preparation worksheet, not a filed return or calculation of tax due. All payment methods, including cash, are included. Earlier-period refunds require separate review for CDTFA credits; they are not deducted from this quarter’s taxable sales above. District allocations, use tax, prior credits, and other return fields must be reviewed separately. See <a href="https://cdtfa.ca.gov/cros/online-filing-instructions.htm" target="_blank" rel="noopener">CDTFA filing instructions</a>. If you report sales excluding tax, do not deduct that tax again.</div><div class="panel section-gap"><h2>Profit and expenses</h2><div class="row"><span>Other selling expenses</span><strong>${money(t.expenses)}</strong></div><div class="row"><span>Miscellaneous business expenses</span><strong>${money(t.miscExpenses)}</strong></div><div class="row"><span>Profit after all entered expenses</span><strong>${money(t.profit)}</strong></div><div class="row"><span>Net product revenue</span><strong>${money(t.productRevenue)}</strong></div><div class="row"><span>Net shipping charged</span><strong>${money(t.shipping)}</strong></div><div class="row"><span>Actual shipping expenses recorded</span><strong>${money(t.shippingCost)}</strong></div><small>${t.missingShipping?t.missingShipping+' shipping expense(s) not entered; profit is incomplete.':'Shipping expenses are included in profit after expenses.'}</small></div><div class="panel section-gap"><h2>Taxable sales by recorded location and rate</h2>${districtTable(ss,same)}</div><div class="panel section-gap"><h2>Sales in this quarter</h2>${saleTable(ss,false)}</div>`;$('#quarter').onchange=e=>{currentQuarter=e.target.value;report();};$('#year').onchange=e=>{currentYear=e.target.value;report();};$('#export').onclick=()=>exportQuarter(ss,rs);}
function districtTable(ss,rs){let rows={};let add=(s,sign)=>{if(!s.taxable)return;let base=taxableBase(s);let rate=base?round(s.tax/base*100):0;let key=(s.location||'Location not entered')+' | '+rate+'% effective';let x=rows[key]||[0,0];x[0]+=sign*taxableBase(s);x[1]+=sign*s.tax;rows[key]=x;};ss.forEach(s=>add(s,1));rs.forEach(r=>add(state.sales.find(s=>s.id===r.sale),-1));return `<div class="table-wrap"><table><thead><tr><th>Location / effective rate</th><th>Net taxable sales</th><th>Net collected tax</th></tr></thead><tbody>${Object.entries(rows).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${money(v[0])}</td><td>${money(v[1])}</td></tr>`).join('')}</tbody></table></div><small>Rate is inferred from actual collected tax. This table does not determine district tax liability.</small>`;}
function download(name,content,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csv(rows){return '\ufeff'+rows.map(row=>row.map(value=>{let s=String(value??'');if(/^[=+@\t\r]/.test(s)||(/^-.+/.test(s)&&!/^-[0-9.]+$/.test(s)))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
function exportQuarter(ss,rs){let rows=[['Type','Date','Customer / reference','SKU','Product','Quantity','Payment','Product sales excluding tax USD','Shipping charged USD','Total revenue excluding tax USD','Tax USD','Total paid/refunded USD','Landed COGS USD','Other selling expenses USD','Actual shipping expense USD','Shipping expense status','Taxable product','Taxable shipping charge USD','Nontaxable shipping charge USD','Location','Reason / notes','Original sale date','Prior-period refund','Color / variant']];let row=(s,d,sign,r)=>[r?'Full refund':'Sale',d,s.reference,product(s.product).sku,product(s.product).name,sign*s.qty,s.payment,round(sign*s.price),round(sign*shipCharge(s)),round(sign*saleRevenue(s)),round(sign*s.tax),round(sign*(saleRevenue(s)+s.tax)),round((!r||r.restock?sign:0)*cost(product(s.product))*s.qty),r?0:s.expense,r?0:s.shippingCost===null?'':s.shippingCost||0,s.shippingCost===null?'Not entered':'Recorded',s.taxable?'Yes':'No',round(sign*shippingTax(s)),round(sign*(shipCharge(s)-shippingTax(s))),s.location,r?r.notes:[s.reason,s.shippingReason,s.notes].filter(Boolean).join(' '),s.date,r&&!inQuarter(s.date)?'Review CDTFA credit':'',saleColor(s)];ss.forEach(s=>rows.push(row(s,s.date,1)));rs.forEach(r=>rows.push(row(state.sales.find(s=>s.id===r.sale),r.date,-1,r)));rows[0].push('Miscellaneous business expense USD','Expense category','Expense payee / event');for(let row of rows.slice(1))row.push('','','');for(let e of (state.businessExpenses||[]).filter(e=>inQuarter(e.date))){let row=Array(27).fill('');row[0]='Business expense';row[1]=e.date;row[6]=e.payment;row[20]=e.notes;row[24]=e.amount;row[25]=e.category;row[26]=e.payee;rows.push(row);}download(`saree-ledger-${currentYear}-Q${currentQuarter}.csv`,csv(rows),'text/csv;charset=utf-8');}
function settings(){$('#view').innerHTML=`<div class="two"><div class="panel"><h2>Your defaults</h2><form id="settingsForm"><div class="fields">${field('Boutique name','name',state.settings.name,'text','required')}${select('Pricing method','pricing',[['margin','Gross profit margin'],['markup','Markup on cost']],state.settings.pricing||'margin')}${num('Target margin / markup %','margin',state.settings.margin,0,'.1')}${num('Default sales tax rate %','tax',state.settings.tax,0,'.001')}${num('Default INR per 1 USD','exchange',state.settings.exchange,.000001,'.000001')}</div><p class="muted">Sales tax starts at 0 until you enter the rate for your business location. Verify each sale’s rate at the <a href="https://www.cdtfa.ca.gov/taxes-and-fees/sales-use-tax-rates.htm" target="_blank" rel="noopener">CDTFA rate page</a>.</p><button id="saveDefaults">Save defaults</button><div id="defaultsStatus" class="save-feedback" data-state="${defaultsFeedback?'success':''}" role="status" aria-live="polite">${esc(defaultsFeedback)}</div></form></div><div class="panel"><h2>Keep a copy</h2><p class="muted">Your computer holds the shared ledger. Export a backup regularly and before changing historical costs.</p><button id="backup">Download full backup</button><h3 class="section-gap">Restore from backup</h3><p class="muted">Restoring replaces the current ledger. Download the current backup first.</p><input id="restore" type="file" accept=".json,application/json"><div class="note">The app also saves the previous ledger to <code>data/last-good-backup.json</code> before every change.</div></div></div><div class="panel section-gap"><h2>Computer + iPhone</h2><p>For computer-only use, open <strong>Start Boutique.bat</strong>. For iPhone access, open <strong>Start Boutique WiFi.bat</strong> and use the address printed in its window. Both devices use the same ledger. Keep your computer awake and connect your iPhone to the same private Wi-Fi.</p><p class="muted">Safari → Share → Add to Home Screen creates a shortcut. The computer must still be running. The Wi-Fi connection uses local HTTP and an access code; use it only on a trusted private network. There is no independent offline iPhone mode or automatic cloud sync.</p></div>`;$('#settingsForm').onsubmit=async e=>{e.preventDefault();let button=e.target.querySelector('button[type="submit"],#saveDefaults'),status=$('#defaultsStatus');button.disabled=true;button.textContent='Saving…';status.textContent='Saving defaults…';status.dataset.state='saving';try{let f=new FormData(e.target);await change(s=>s.settings={name:f.get('name'),pricing:f.get('pricing'),margin:+f.get('margin'),tax:+f.get('tax'),exchange:+f.get('exchange')});defaultsFeedback='Saved successfully at '+new Date().toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})+'.';let current=$('#defaultsStatus');if(current){current.textContent=defaultsFeedback;current.dataset.state='success';}notice('Defaults saved.');}catch(err){defaultsFeedback='';let current=$('#defaultsStatus');if(current){current.textContent='Not saved: '+err.message;current.dataset.state='error';}notice(err.message,true);}finally{button.disabled=false;button.textContent='Save defaults';}};$('#settingsForm').oninput=()=>{defaultsFeedback='';let status=$('#defaultsStatus');status.textContent='Unsaved changes';status.dataset.state='changed';};$('#backup').onclick=async()=>{let button=$('#backup');button.disabled=true;notice('Preparing a full backup, including all photos…');try{let full=state.lazyPhotos?await api('/api/state?full=1',undefined,120000):state;download('saree-backup-'+today()+'.json',JSON.stringify(full,null,2),'application/json');notice('Full backup downloaded, including photos.');}catch(e){notice('Backup failed: '+e.message,true);}finally{button.disabled=false;}};$('#restore').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{let imported=JSON.parse(await file.text());if(!confirm('Replace your current ledger with this backup? Download the current backup first.'))return;imported.revision=state.revision;state=await api('/api/restore',imported);render();notice('Backup restored.');}catch(err){notice('Restore failed: '+err.message,true);}};}

function labelItems(products){return products.flatMap(p=>{let rows=(p.variants||[]).filter(v=>variantStock(p,v)>0).map(v=>({p,v,stock:variantStock(p,v),copies:1}));let stock=unassignedStock(p);if(stock>0)rows.push({p,v:null,stock,copies:1});return rows;});}
function labelCanvas(item,width,height){let c=document.createElement('canvas');c.width=Math.round(width/25.4*300);c.height=Math.round(height/25.4*300);let ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.fillStyle='#000';ctx.textAlign='center';ctx.textBaseline='middle';let pad=w*.055;
 function text(value,y,size,bold=false){value=String(value);let f=size;do{ctx.font=`${bold?'700':'400'} ${f}px Arial`;if(ctx.measureText(value).width<=w-2*pad)break;f-=1;}while(f>7);ctx.fillText(value,w/2,y,w-2*pad);}
 text(state.settings.name,h*.12,h*.075,true);text(item.p.name,h*.26,h*.065);text(item.v?item.v.name:'',h*.36,h*.07,true);text(money(roundedLabelPrice(item.p)),h*.57,h*.24,true);text('Tax included',h*.76,h*.08,true);text(item.p.sku,h*.9,h*.06);return c;}
function labelsForm(products){let items=labelItems(products);if(!items.length){notice('There are no on-hand pieces in this selection.',true);return;}let width=40,height=30;
 dialog('Price labels',`<p>SUPVAN T50M Pro: save a label image, import it in your SUPVAN app, and set the number of copies there. Labels show the price with default tax included.</p><form id="labelForm"><div class="fields">${select('Label size','labelSize',[['40x30','40 × 30 mm'],['50x30','50 × 30 mm'],['50x80','50 × 80 mm'],['custom','Custom size']],'40x30')}${num('Width · mm','labelWidth',40,20,1)}${num('Height · mm','labelHeight',30,15,1)}</div><small>Check the dimensions on your installed label roll. Size is adjustable; 40 × 30 mm is the starting preset.</small><div class="row actions"><button type="button" class="quiet" id="oneEach">One of each</button><button type="button" class="quiet" id="onePerPiece">One per piece on hand</button><button type="button" class="quiet" id="clearLabels">Clear selection</button></div><div class="table-wrap"><table><thead><tr><th>Product / color</th><th>Tax included</th><th>Copies</th></tr></thead><tbody>${items.map((item,i)=>`<tr><td>${esc(item.p.name)}<br><small>${esc(item.p.sku)} · ${esc(item.v?.name||'Unassigned')} · ${item.stock} on hand</small></td><td><strong>${money(roundedLabelPrice(item.p))}</strong></td><td><input type="number" min="0" max="500" step="1" value="1" data-copies="${i}" aria-label="Copies for ${esc(item.p.sku+' '+(item.v?.name||'Unassigned'))}"></td></tr>`).join('')}</tbody></table></div><div id="labelStatus" role="status"></div><div class="row actions"><button type="button" id="previewLabels">Preview labels</button><button type="button" class="quiet" id="browserPrint">Browser print / PDF</button></div><small>Browser printing: use the matching paper size, 100% scale, no margins, and turn off headers/footers. For the SUPVAN mobile app, use the PNG image buttons below.</small><div id="labelPreview" class="label-previews"></div></form>`);
 let form=$('#labelForm');function sync(){width=Number(form.elements.labelWidth.value);height=Number(form.elements.labelHeight.value);if(!Number.isFinite(width)||width<20||width>100||!Number.isFinite(height)||height<15||height>150)throw new Error('Enter width 20–100 mm and height 15–150 mm.');form.querySelectorAll('[data-copies]').forEach(el=>{let n=Number(el.value);if(!Number.isInteger(n)||n<0||n>500)throw new Error('Copies must be whole numbers between 0 and 500.');items[+el.dataset.copies].copies=n;});let count=items.reduce((n,x)=>n+x.copies,0);if(count>500)throw new Error('Print at most 500 labels at a time.');return count;}
 function renderPreview(){try{let count=sync();let selected=items.filter(x=>x.copies>0);$('#labelStatus').textContent=`${count} labels · ${width} × ${height} mm · ${state.settings.tax}% default tax included`;
 $('#labelPreview').innerHTML=selected.map(item=>{let i=items.indexOf(item);return `<div class="label-preview"><img src="${labelCanvas(item,width,height).toDataURL('image/png')}" alt="${esc(item.p.name+' '+(item.v?.name||'')+' '+money(roundedLabelPrice(item.p))+' Tax included')}" style="aspect-ratio:${width}/${height}"><small>${item.copies} copies · ${esc(item.p.sku)}</small><button type="button" class="quiet" data-label-image="${i}">Download PNG</button>${navigator.share?`<button type="button" class="quiet" data-label-image="${i}" data-share>Share PNG</button>`:''}</div>`;}).join('');$('#labelPreview').querySelectorAll('[data-label-image]').forEach(b=>b.onclick=async()=>{try{sync();let item=items[+b.dataset.labelImage],canvas=labelCanvas(item,width,height),blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png')),filename=(item.p.sku+'-'+(item.v?.name||'unassigned')).replace(/[^a-zA-Z0-9_-]/g,'_')+'.png',file=new File([blob],filename,{type:'image/png'});if(b.hasAttribute('data-share')&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Price label'});}else{let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}}catch(e){if(e.name!=='AbortError')formError(e);}});
 }catch(e){formError(e);}}
 function copies(fn){form.querySelectorAll('[data-copies]').forEach(el=>el.value=fn(items[+el.dataset.copies]));renderPreview();}
 $('#oneEach').onclick=()=>copies(()=>1);$('#onePerPiece').onclick=()=>copies(x=>x.stock);$('#clearLabels').onclick=()=>copies(()=>0);$('#previewLabels').onclick=renderPreview;
 form.elements.labelSize.onchange=e=>{if(e.target.value!=='custom'){let [w,h]=e.target.value.split('x');form.elements.labelWidth.value=w;form.elements.labelHeight.value=h;renderPreview();}};
 form.oninput=e=>{if(['labelWidth','labelHeight'].includes(e.target.name))form.elements.labelSize.value='custom';$('#labelStatus').textContent='Selection changed. Preview or print to apply.';};
 $('#browserPrint').onclick=()=>{try{let count=sync();if(!count)throw new Error('Choose at least one label.');let area=$('#printArea');if(!area){area=document.createElement('section');area.id='printArea';document.body.append(area);}let style=$('#labelPrintStyle');if(!style){style=document.createElement('style');style.id='labelPrintStyle';document.head.append(style);}style.textContent=`@media print{@page{size:${width}mm ${height}mm;margin:0}#printArea .printed-label{width:${width}mm;height:${height}mm;}}`;area.innerHTML=items.filter(x=>x.copies>0).map(item=>{let src=labelCanvas(item,width,height).toDataURL('image/png');return Array.from({length:item.copies},()=>`<div class="printed-label"><img src="${src}" alt="${esc(item.p.sku)}"></div>`).join('');}).join('');Promise.all([...area.querySelectorAll('img')].map(img=>img.decode())).then(()=>window.print()).catch(formError);}catch(e){formError(e);}};
 form.onsubmit=e=>{e.preventDefault();renderPreview();};renderPreview();
}

async function logout(){let button=$('#logout');button.disabled=true;try{await api('/api/logout',{});state=null;defaultsFeedback='';page='Overview';$('#nav').innerHTML='';$('#view').innerHTML='<div class="empty"><h2>Signed out</h2><p>Enter your access code to open the ledger.</p></div>';$('#connection').textContent='Signed out';notice('');button.hidden=true;login();}catch(error){notice('Could not sign out: '+error.message,true);}finally{button.disabled=false;}}
$('#logout').onclick=logout;
$('#refresh').onclick=load;
load();
// Core functions are shared with the calculation tests, without requiring a UI library.

function historicalReview(){let pending=(state.pending||[]).filter(p=>p.qty>0);$('#view').innerHTML=`<div class="note">These workbook sales reduced opening inventory but have not entered tax or profit reports. Review individual dates, payment methods, actual amounts, and tax. Cash sales belong in the same ledger. Original workbook notes remain visible.</div><div class="panel"><h2>Imported sales awaiting review</h2><p>${pending.reduce((n,p)=>n+p.qty,0)} sold pieces · ${money(pending.reduce((n,p)=>n+p.total,0))} unreviewed receipts</p>${pending.map(p=>`<div class="panel section-gap"><div class="row"><h3>${esc(product(p.product).name)}</h3><span class="tag">${p.qty} pieces</span></div><p>${esc(p.notes)}</p><div class="row"><span>Remaining workbook receipts: ${money(p.total)}</span><button data-review="${p.id}">Review a sale</button></div></div>`).join('')||'<p class="muted">All imported sales have been reviewed.</p>'}</div>`;document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>historyForm(b.dataset.review));}
function historyForm(id){let pending=state.pending.find(p=>p.id===id);dialog('Review imported sale',`<p class="muted">${esc(pending.notes)}</p><form id="editForm"><div class="fields">${field('Actual sale date','date','','date','required')}${num('Pieces in this transaction','qty',1,1,1)}${num('Actual total paid including tax · USD','total',round(pending.total/pending.qty))}${num('Actual sales tax collected · USD','tax',0)}${select('Payment method','payment',['Zelle','Venmo','Cash','Other'].map(x=>[x,x]),'Other')}${field('City / tax district','location','')}${select('Tax treatment','taxable',[['yes','Taxable'],['no','Nontaxable with documentation']],'yes')}${field('Customer / reference','reference','')}<label class="full">Notes / nontaxable documentation<textarea name="reason"></textarea></label></div><div class="row actions"><button type="button" class="quiet" id="legacyTax">Extract included tax using ${state.settings.tax}%</button></div><div class="note">Enter actual tax when known. The extraction button assumes the configured rate applied to the entire total. Editing the receipt total adjusts the unreviewed balance; no workbook quarterly figures are imported.</div>${foot('Add verified sale')}</form>`);let f=$('#editForm');$('#legacyTax').onclick=()=>{let total=+f.elements.total.value;f.elements.tax.value=round(total-total/(1+state.settings.tax/100));};wireForm(async d=>{let qty=+d.get('qty'),total=+d.get('total'),tax=+d.get('tax');if(qty>pending.qty)throw new Error('Quantity exceeds unreviewed pieces');if(tax>total)throw new Error('Tax exceeds total paid');await change(s=>{let entry=s.pending.find(p=>p.id===id);entry.qty-=qty;entry.total=entry.qty?Math.max(0,round(entry.total-total)):0;s.products.find(p=>p.id===entry.product).openingSold-=qty;s.sales.push({id:uid(),product:entry.product,date:d.get('date'),qty,price:round(total-tax),tax,expense:0,payment:d.get('payment'),taxable:d.get('taxable')==='yes',reason:d.get('reason'),location:d.get('location'),reference:d.get('reference'),notes:'Reviewed workbook sale: '+entry.notes});});});}

function shippingForm(id){let sale=state.sales.find(s=>s.id===id);dialog('Shipping for this sale',`<p>${esc(sale.reference||'Customer')} · ${esc(sale.date)} · Total already paid: ${money(saleRevenue(sale)+sale.tax)}</p><form id="editForm"><div class="fields">${num('Product sale before tax · USD','price',sale.price)}${num('Shipping charged to customer · USD','shippingCharge',shipCharge(sale))}${field('Actual postage / shipping expense · USD (blank = not entered)','shippingCost',sale.shippingCost===null?'':sale.shippingCost||0,'number','min="0" step=".01"')}${num('Taxable portion of shipping charge · USD','shippingTaxable',shippingTax(sale))}<label class="full">Shipping receipt / tracking / exemption notes<textarea name="shippingReason">${esc(sale.shippingReason)}</textarea></label></div><div class="note">This can split a previously recorded total into product and shipping income. The total before tax must remain ${money(saleRevenue(sale))}. Collected tax remains unchanged. Full refunds include the shipping charge; actual postage expenses remain costs. For multi-product orders, enter the shipping charge and expense on only one sale entry.</div>${foot('Save shipping details')}</form>`);wireForm(async d=>{let price=+d.get('price'),charge=+d.get('shippingCharge');if(round(price+charge)!==round(saleRevenue(sale)))throw new Error('Product plus shipping must equal the original total before tax');await change(s=>{let item=s.sales.find(s=>s.id===id);item.price=price;item.shippingCharge=charge;item.shippingCost=d.get('shippingCost')===''?(charge>0?null:0):+d.get('shippingCost');item.shippingTaxable=+d.get('shippingTaxable');item.shippingReason=d.get('shippingReason');});});}
